-- parameters: []
SELECT lips."VBELN" AS delivery, ROW_NUMBER() OVER (PARTITION BY lips."MATNR" ORDER BY lips."VBELN" ASC) AS position, RANK() OVER (ORDER BY lips."LFIMG" DESC) AS ranking, DENSE_RANK() OVER (ORDER BY lips."LFIMG" DESC) AS dense, LAG(lips."VBELN", 1) OVER (ORDER BY lips."VBELN" ASC) AS previous, LEAD(lips."VBELN", 2) OVER (ORDER BY lips."VBELN" ASC) AS next, SUM(lips."LFIMG") OVER (PARTITION BY lips."MATNR" ORDER BY lips."VBELN" ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running, AVG(lips."LFIMG") OVER (ORDER BY lips."VBELN" ASC ROWS BETWEEN 2 PRECEDING AND 1 FOLLOWING) AS moving
FROM "QUERY_IT"."LIPS" lips
